+ACTIVE MIGRATIONS: 062_consolidated_baseline.sql, 063_report_crypto_search_path.sql, 064_explicit_report_context.sql, 065_remove_dhash_hardblock.sql, 066_push_and_carryover_hardening.sql, 067_admin_direct_notification_popup.sql, 068_owner_tester_reports_count.sql, 069_admin_audit_hardening.sql, 070_admin_management.sql, 071_business_policies.sql, 072_admin_notification_campaigns.sql, 073_admin_action_audit.sql, 074_app_mission_window_and_multi_attachments.sql, 075_owner_auto_pause_config.sql, 076_mission_for_finalized_campaigns.sql, 077_mission_reward_modes_and_management.sql, 078_admin_pause_reason_popup.sql, 079_owner_auto_pause_debt_and_timestamp_guard.sql
