+PASS: Supply matrix C=2, A=5, D=5 {"mode":"owner","base_required_tests":6,"carry_in_tests":2,"available_apps":5,"completed_tests":5,"effective_required_tests":5,"carryover_remaining_tests":0,"met":true,"carryover_ready":true,"history_ready":true}
+PASS: Supply matrix C=8, A=5, D=5 {"mode":"owner","base_required_tests":6,"carry_in_tests":8,"available_apps":5,"completed_tests":5,"effective_required_tests":5,"carryover_remaining_tests":3,"met":true,"carryover_ready":true,"history_ready":true}
